// Generated by site/build.py. Confirms an email or sets a new password, only on tap.
(() => {
  const SUPABASE_URL = "https://bcknlvhcmghztqwyqudq.supabase.co";
  const PUBLISHABLE_KEY = "sb_publishable_qTO4Xby6sojNrfTWvzwipA_11AgFCo3";
  const params = new URLSearchParams(location.search);
  const tokenHash = params.get("token_hash");
  const type = params.get("type");
  const $ = (id) => document.getElementById(id);
  const show = (id) => ["confirm-ready", "reset-ready", "working", "confirmed", "reset-done", "failed"]
    .forEach((x) => { $(x).hidden = x !== id; });
  const fail = () => {
    $("failed-hint").textContent = type === "recovery"
      ? "Request a new one in Let's Sip: Sign in → Forgot password."
      : "If you already confirmed, just sign in to the app. Otherwise, sign up again in Let's Sip with the same email and we'll send a new link.";
    show("failed");
  };
  const verify = async () => {
    const response = await fetch(SUPABASE_URL + "/auth/v1/verify", {
      method: "POST",
      headers: { apikey: PUBLISHABLE_KEY, "Content-Type": "application/json" },
      body: JSON.stringify({ type, token_hash: tokenHash }),
    });
    if (!response.ok) throw new Error("verify");
    return (await response.json().catch(() => ({}))).access_token;
  };
  // This browser is signed in only for a moment; the app is where the account is used.
  const signOut = (token) => fetch(SUPABASE_URL + "/auth/v1/logout?scope=local", {
    method: "POST", headers: { apikey: PUBLISHABLE_KEY, Authorization: "Bearer " + token },
  }).catch(() => {});

  if (!tokenHash || (type !== "email" && type !== "recovery")) { fail(); return; }
  // Keep the one-time token out of the address bar and browser history.
  history.replaceState(null, "", location.pathname);
  $("title").textContent = type === "recovery" ? "Reset your password" : "Confirm your email";

  if (type === "email") {
    show("confirm-ready");
    $("confirm").addEventListener("click", async () => {
      show("working");
      try {
        const token = await verify();
        if (token) signOut(token);
        show("confirmed");
      } catch { fail(); }
    });
  } else {
    show("reset-ready");
    $("reset").addEventListener("click", async () => {
      const password = $("password").value;
      if (password.length < 6) { $("password").focus(); return; }
      show("working");
      try {
        const token = await verify();
        const saved = await fetch(SUPABASE_URL + "/auth/v1/user", {
          method: "PUT",
          headers: { apikey: PUBLISHABLE_KEY, Authorization: "Bearer " + token, "Content-Type": "application/json" },
          body: JSON.stringify({ password }),
        });
        signOut(token);
        if (!saved.ok) throw new Error("save");
        show("reset-done");
      } catch { fail(); }
    });
  }
})();
